typedef struct {
    volatile uint32_t MODER;    /* 0x00 - mode register        */
    volatile uint32_t OTYPER;   /* 0x04 - output type          */
    volatile uint32_t OSPEEDR;  /* 0x08 - output speed         */
    volatile uint32_t PUPDR;    /* 0x0C - pull-up / pull-down  */
    volatile uint32_t IDR;      /* 0x10 - input data           */
    volatile uint32_t ODR;      /* 0x14 - output data          */
    volatile uint32_t BSRR;     /* 0x18 - bit set/reset        */
} GPIO_t;

#define GPIOA  ((GPIO_t *)0x48000000UL)

/* Blink an LED on PA5, bare metal, no libraries. */
#include "stm32l4xx.h"                    /* register map only (CMSIS device header) */

int main(void)
{
    RCC->AHB2ENR |= (1u << 0);            /* clock for GPIOA */
    (void)RCC->AHB2ENR;                   /* read back: let the clock start */

    GPIOA->MODER &= ~(3u << (5 * 2));     /* clear mode bits for pin 5 */
    GPIOA->MODER |=  (1u << (5 * 2));     /* 01 = general purpose output */

    for (;;) {
        GPIOA->BSRR = (1u << 5);          /* set */
        for (volatile uint32_t i = 0; i < 400000u; i++) { }
        GPIOA->BSRR = (1u << (5 + 16));   /* clear */
        for (volatile uint32_t i = 0; i < 400000u; i++) { }
    }
}

/* Correct: blocks, releasing the CPU. */
vTaskDelay(pdMS_TO_TICKS(100));

/* Wrong: burns the CPU and starves lower-priority tasks. */
for (volatile int i = 0; i < 100000; i++) { }

/* ISR side: signal the task and yield if it is now the highest priority. */
void EXTI0_IRQHandler(void)
{
    BaseType_t woken = pdFALSE;
    EXTI->PR1 = EXTI_PR1_PIF0;          /* clear the pending flag first */
    xSemaphoreGiveFromISR(sem_dato, &woken);
    portYIELD_FROM_ISR(woken);
}

/* Task side: block until signalled, with a timeout. */
for (;;) {
    if (xSemaphoreTake(sem_dato, pdMS_TO_TICKS(500)) == pdTRUE) {
        procesar();
    } else {
        registrar_fallo();      /* the timeout is not optional */
    }
}

